# 02. Sediment bacterial communities in the Strait of Magellan ----
# Run from the same folder as 01_DADA2.R, in a fresh R session.
# The only data files read here are taxa.silva.xlsx (generated by 01) and Env.csv (field observations).
# Sections can be run one at a time in RStudio. Asterisks indicate the documented package versions.
# R for the revised ecological analyses: 4.5.3.

# 1. Open the counts from DADA2 and remove the control signal ----
library(readxl)       # * 1.4.5
library(microDecon)   # * 1.0.2
taxa.silva <- as.data.frame(read_excel("taxa.silva.xlsx", sheet = "counts", .name_repair = "minimal"))
control_ids <- c("Blank1", "Blank2", "Blank3")
stopifnot(identical(names(taxa.silva)[1:4], c("OTU_ID", control_ids)), ncol(taxa.silva) == 35L,
          !anyNA(taxa.silva$OTU_ID), !anyDuplicated(taxa.silva$OTU_ID), !anyDuplicated(names(taxa.silva)))
raw_all <- as.matrix(taxa.silva[, -1, drop = FALSE])
rownames(raw_all) <- taxa.silva$OTU_ID
stopifnot(is.numeric(raw_all), all(is.finite(raw_all)), all(raw_all >= 0), all(raw_all == round(raw_all)))
# One pooled decon run across 31 environmental samples, with all three control columns first.
clean.16S <- microDecon::decon(data = taxa.silva, numb.blanks = 3, numb.ind = 31, taxa = FALSE,
                               runs = 2, thresh = 0.7, prop.thresh = 5e-5, regression = 0,
                               low.threshold = 40, up.threshold = 400)
clean.16S <- clean.16S$decon.table
print(dim(clean.16S))

# 2. Add taxonomy and field data; construct the phyloseq objects ----
library(phyloseq)     # * 1.48.0
library(vegan)        # * 2.7-3
library(permute)      # * 0.9-10
library(iNEXT)        # * 3.0.2
library(missForest)   # * 1.6.1 (ranger 0.18.0)
library(readr)        # * 2.1.5 (export TSVs)
library(dplyr)        # * 1.1.4
library(tidyr)        # * 1.3.1
library(ggplot2)      # * 4.0.3
library(ggrepel)      # * 0.9.6
library(ggalluvial)   # * 0.12.6
library(patchwork)    # * 1.3.0
library(svglite)      # * 2.2.0

Env <- read.csv("Env.csv", check.names = FALSE, stringsAsFactors = FALSE, na.strings = "NA")
tax_sheet <- as.data.frame(read_excel("taxa.silva.xlsx", sheet = "taxonomy", .name_repair = "minimal"))
stopifnot(!anyNA(Env$ID), !anyDuplicated(Env$ID), setequal(Env$ID, colnames(raw_all)[-seq_len(3)]),
          sum(Env$Type == "Sediment") == 25L, sum(Env$Type == "Sea_Water") == 6L,
          !anyDuplicated(tax_sheet$ASV), !anyDuplicated(tax_sheet$Sequence),
          !anyNA(tax_sheet$Sequence), setequal(tax_sheet$ASV, rownames(raw_all)),
          all(c("Kingdom", "Phylum", "Class", "Order", "Family", "Genus") %in% names(tax_sheet)))
taxonomy <- tax_sheet[, c("ASV", "Kingdom", "Phylum", "Class", "Order", "Family", "Genus")]
rownames(taxonomy) <- taxonomy$ASV
rownames(Env) <- Env$ID
metadata <- Env[, c("ID", "Site", "Type", "Date")]
environment <- Env[Env$Type == "Sediment", , drop = FALSE]
# Select environmental columns by ID. The pooled blank column from microDecon is not a sample.
stopifnot(all(metadata$ID %in% names(clean.16S)), !anyDuplicated(clean.16S$OTU_ID))
clean_counts <- as.matrix(clean.16S[, metadata$ID, drop = FALSE])
rownames(clean_counts) <- clean.16S$OTU_ID
stopifnot(all(is.finite(clean_counts)), all(clean_counts >= 0), all(clean_counts == round(clean_counts)))

output <- "results"
for (folder in c("tables", "figures", "objects", "supplement"))
  dir.create(file.path(output, folder), recursive = TRUE, showWarnings = FALSE)
RNGkind("Mersenne-Twister", "Inversion", "Rejection")
sites <- c("Bahia_Buzo", "San_Gregorio", "Buque_Quemado")
dates <- c("August", "March")
cohorts <- c("With_BB05", "Without_BB05")
coverage_target <- 0.9998
nperm <- 9999L
seed <- 123L
site_colors <- c(Bahia_Buzo = "#1b9e77", San_Gregorio = "#d95f02", Buque_Quemado = "#7570b3")
site_labels <- c(Bahia_Buzo = "Bahía Buzo", San_Gregorio = "San Gregorio", Buque_Quemado = "Buque Quemado")
date_shapes <- c(August = 21, March = 24)
write_tsv(tax_sheet[, c("ASV", "Sequence")], file.path(output, "tables/ASV_to_sequence.tsv"))
# No singleton or occurrence cutoff for the primary matrix. Organellar reads and ASVs not
# explicitly assigned to Bacteria are excluded. Water remains available for the phylum figure.

tax <- taxonomy[rownames(clean_counts), , drop = FALSE]
stopifnot(!anyNA(tax$ASV))
taxonomic_keep <- tax$Kingdom %in% "Bacteria" & !(tax$Order %in% "Chloroplast") &
                  !(tax$Family %in% "Mitochondria")
bacterial_31 <- clean_counts[taxonomic_keep, , drop = FALSE]
bacterial_31 <- bacterial_31[rowSums(bacterial_31) > 0, , drop = FALSE]

# Counts are ASV x sample. Occurrence counts samples with a positive count, not reads.
N <- rowSums(clean_counts > 0)
sample_ids <- sort(metadata$ID[metadata$Type == "Sediment"], method = "radix")
main_counts <- bacterial_31[, sample_ids, drop = FALSE]
main_counts <- main_counts[rowSums(main_counts) > 0, , drop = FALSE]
filtered_counts <- main_counts[N[rownames(main_counts)] > 1, , drop = FALSE]
# Logical subsetting preserves the actual microDecon ASV order. No external
# list of filtered ASV identifiers or precomputed occurrence assignments is needed.
matrices <- list(Primary_bacteria = main_counts, Occurrence_filtered_bacteria = filtered_counts)
meta <- metadata[sample_ids, , drop = FALSE]
meta$Site <- factor(meta$Site, levels = sites)
meta$Date <- factor(meta$Date, levels = dates)
meta$Group <- interaction(meta$Site, meta$Date, drop = TRUE)
sample_sets <- list(With_BB05 = sample_ids, Without_BB05 = setdiff(sample_ids, "BB_05"))
print(data.frame(Matrix = names(matrices), Sediments = ncol(main_counts),
                 ASVs = vapply(matrices, nrow, integer(1)),
                 Reads = vapply(matrices, sum, numeric(1))), row.names = FALSE)

# Join observed geochemistry by ID. The six water samples have no sediment chemistry.
metadata_full <- metadata
environment_names <- c("Organic Matter (%)", "Total N (%)", "Olsen P (mg/kg)")
metadata_full[, environment_names] <- environment[match(metadata_full$ID, environment$ID), environment_names]
ps_all <- phyloseq(otu_table(bacterial_31, taxa_are_rows = TRUE),
                   tax_table(as.matrix(taxonomy[rownames(bacterial_31), -1, drop = FALSE])),
                   sample_data(metadata_full))
Sed_16S <- phyloseq(otu_table(main_counts, taxa_are_rows = TRUE),
                   tax_table(as.matrix(taxonomy[rownames(main_counts), -1, drop = FALSE])),
                   sample_data(metadata_full[sample_ids, , drop = FALSE]))
sed <- Sed_16S
sed_no_BB05 <- prune_samples(sample_names(sed) != "BB_05", sed)
sed_no_BB05 <- prune_taxa(taxa_sums(sed_no_BB05) > 0, sed_no_BB05)
ps_water <- prune_samples(metadata_full$ID[metadata_full$Type == "Sea_Water"], ps_all)
ps_water <- prune_taxa(taxa_sums(ps_water) > 0, ps_water)
stopifnot(nsamples(sed_no_BB05) == 24L, nsamples(ps_all) == 31L, nsamples(ps_water) == 6L)
saveRDS(ps_all, "results/objects/Bacteria_sediment_and_water.rds")
saveRDS(sed, "results/objects/Sed_16S_primary.rds")
saveRDS(ps_water, "results/objects/Bacteria_seawater.rds")
readr::write_tsv(data.frame(ASV = rownames(main_counts), main_counts, check.names = FALSE),
          "results/tables/primary_counts.tsv")
print(sed)
print(table(meta$Site, meta$Date))


# 3. Observed Hill numbers and coverage-standardized diversity ----
# Use biological samples as replicates and point estimates at common coverage.
# Coverage standardization uses interpolation; bootstrap uncertainty is not
# propagated into the site comparisons.
hill_rows <- coverage_rows <- list()

for (matrix_name in names(matrices)) {
  message("Hill diversity and coverage: ", matrix_name)
  counts <- matrices[[matrix_name]]
  for (id in colnames(counts)) {
    abundance <- counts[, id]
    abundance <- abundance[abundance > 0]
    reads <- sum(abundance)
    f1 <- sum(abundance == 1)
    f2 <- sum(abundance == 2)
    f0 <- if (f2 == 0)
      (reads - 1)/reads * f1 * (f1 - 1)/2 else (reads - 1)/reads * f1^2/(2 * f2)
    A <- if (f1 > 0)
      reads * f0/(reads * f0 + f1) else 1
    observed_coverage <- 1 - f1/reads * A
    info <- iNEXT::DataInfo(as.numeric(abundance), datatype = "abundance")
    stopifnot(min(abs(info$SC - observed_coverage), abs(info$SC - round(observed_coverage,
      4))) < 1e-10, observed_coverage >= coverage_target)
    observed <- c(length(abundance), exp(diversity(abundance, "shannon")), diversity(abundance,
      "invsimpson"))
    standardized <- iNEXT::estimateD(setNames(list(as.numeric(abundance)), id), q = 0:2,
      datatype = "abundance", base = "coverage", level = coverage_target, nboot = 0)
    standardized <- standardized[match(0:2, standardized$Order.q), ]
    stopifnot(all(abs(standardized$SC - coverage_target) < 1e-07), all(standardized$m <=
      reads + 1e-06), !any(grepl("extrap", standardized$Method, ignore.case = TRUE)))
    for (estimation in c("Observed", "Common_coverage")) {
      values <- if (estimation == "Observed")
        observed else standardized$qD
      hill_rows[[length(hill_rows) + 1L]] <- data.frame(Matrix = matrix_name, Estimate = estimation,
        ID = id, Site = as.character(meta[id, "Site"]), Date = as.character(meta[id,
          "Date"]), Reads = reads, Observed_coverage = observed_coverage, D0 = values[1],
        D1 = values[2], D2 = values[3])
    }
    coverage_rows[[length(coverage_rows) + 1L]] <- data.frame(Matrix = matrix_name, ID = id,
      f1 = f1, f2 = f2, Observed_coverage = observed_coverage, Target_coverage = coverage_target,
      m = standardized$m[1], Extrapolated = FALSE)
  }
}
hill <- bind_rows(hill_rows)
coverage <- bind_rows(coverage_rows)
readr::write_tsv(hill, "results/tables/Hill_sample_level.tsv")
readr::write_tsv(coverage, "results/tables/coverage.tsv")

# Inspect the primary values as two separate sample tables.
hill_observed <- subset(hill, Matrix == "Primary_bacteria" & Estimate == "Observed")
hill_standardized <- subset(hill, Matrix == "Primary_bacteria" & Estimate == "Common_coverage")
hill_counts <- t(main_counts)
meta_hill <- meta[rownames(hill_counts), , drop = FALSE]
D0 <- specnumber(hill_counts)
D1 <- exp(diversity(hill_counts, index = "shannon"))
D2 <- diversity(hill_counts, index = "invsimpson")
stopifnot(max(abs(D0 - hill_observed$D0)) < 1e-12, max(abs(D1 - hill_observed$D1)) < 1e-09,
  max(abs(D2 - hill_observed$D2)) < 1e-09)
print(range(coverage$Observed_coverage[coverage$Matrix == "Primary_bacteria"]))
hill_summary <- hill_standardized %>%
  group_by(Date, Site) %>%
  summarise(n = n(), D0_median = median(D0), D0_IQR = IQR(D0), D1_median = median(D1),
    D1_IQR = IQR(D1), D2_median = median(D2), D2_IQR = IQR(D2), .groups = "drop")
print(hill_summary)
readr::write_tsv(hill_summary, "results/tables/Hill_primary_descriptors.tsv")

# 4. Compare alpha diversity among sites within each sampling period ----
# These two short functions perform the exact tests. The loops immediately below them
# specify which samples enter each comparison; no permutation subsampling is used here.
exact_kw <- function(values, groups) {
  groups <- droplevels(factor(groups))
  stopifnot(length(values) == length(groups), !anyNA(groups), all(is.finite(values)),
    nlevels(groups) == 3L)
  # Rank after rounding to eight decimal places to avoid floating-point differences in near ties.
  x <- round(values, digits = -floor(log10(sqrt(.Machine$double.eps))))
  ranks2 <- 2 * rank(x, ties.method = "average")
  sizes <- as.integer(table(groups))
  n <- length(x)
  coefficients <- prod(sizes)/sizes
  observed_sums <- vapply(levels(groups), function(s) {
    sum(ranks2[groups == s])
  }, numeric(1))
  observed_statistic <- sum(observed_sums^2 * coefficients)
  greater_or_equal <- 0
  allocations <- 0
  # Enumerate allocations to the first two sites; the third gets the remainder.
  # Twice-midranks and integer coefficients avoid floating-point tail ambiguity.
  for (first_group in combn(seq_len(n), sizes[1], simplify = FALSE)) {
    remaining <- setdiff(seq_len(n), first_group)
    second_group <- combn(remaining, sizes[2])
    s1 <- sum(ranks2[first_group])
    s2 <- colSums(matrix(ranks2[second_group], nrow = sizes[2]))
    s3 <- sum(ranks2) - s1 - s2
    statistics <- s1^2 * coefficients[1] + s2^2 * coefficients[2] + s3^2 * coefficients[3]
    greater_or_equal <- greater_or_equal + sum(statistics >= observed_statistic)
    allocations <- allocations + length(statistics)
  }
  stopifnot(allocations == round(exp(lfactorial(n) - sum(lfactorial(sizes)))))
  H <- if (length(unique(x)) == 1)
    0 else unname(kruskal.test(x, groups)$statistic)
  data.frame(n = n, df = 2L, H = H, p_exact = greater_or_equal/allocations, Allocations = allocations,
    Adjustment_family = "Global tests: unadjusted")
}

exact_wilcox_pairs <- function(values, groups, global_p) {
  groups <- droplevels(factor(groups))
  stopifnot(length(values) == length(groups), !anyNA(groups), all(is.finite(values)),
    nlevels(groups) == 3L, length(global_p) == 1L, is.finite(global_p))
  results <- list()
  for (pair in combn(levels(groups), 2, simplify = FALSE)) {
    a <- values[groups == pair[1]]
    b <- values[groups == pair[2]]
    n1 <- length(a)
    n2 <- length(b)
    ranks <- rank(c(a, b), ties.method = "average")
    observed_sum <- sum(ranks[seq_len(n1)])
    permuted_sums <- combn(seq_along(ranks), n1, FUN = function(j) sum(ranks[j]))
    p_pair <- min(1, 2 * min(mean(permuted_sums <= observed_sum), mean(permuted_sums >=
      observed_sum)))
    results[[length(results) + 1L]] <- data.frame(Site1 = pair[1], Site2 = pair[2],
      n1 = n1, n2 = n2, W = observed_sum - n1 * (n1 + 1)/2, p_exact = p_pair, Allocations = length(permuted_sums),
      Smallest_two_sided_p_no_ties = 2/choose(n1 + n2, n1), Cliff_delta = mean(sign(outer(a,
        b, "-"))), Global_gate = global_p < 0.05)
  }
  result <- do.call(rbind, results)
  result$p_Holm <- p.adjust(result$p_exact, method = "holm")
  result$Pair_supported <- result$Global_gate & result$p_Holm <
    0.05
  result$Adjustment_family <- "Three site pairs within matrix, cohort, date and Hill order"
  result
}

# The same tests run for both matrices and both BB_05 cohorts. Inspect each result by its labels.
# Exact KW: all allocations of the observed ranks to the three fixed group sizes, inclusive tail.
# All three exact two-sided Wilcoxon tests are reported. Holm is applied WITHIN date and order.
# The global p is unadjusted. A post hoc conclusion requires BOTH global_p and p_Holm < 0.05.
KW_rows <- pair_rows <- list()
for (matrix_name in names(matrices)) for (cohort in cohorts) {
  for (estimation in c("Common_coverage", "Observed")) for (date in dates) {
    d <- hill[hill$Matrix == matrix_name & hill$Estimate == estimation & hill$Date == date &
              hill$ID %in% sample_sets[[cohort]], , drop = FALSE]
    d$Site <- factor(d$Site, levels = sites)
    d <- d[order(d$Site, d$ID), , drop = FALSE]
    for (index in c("D0", "D1", "D2")) {
      kw <- exact_kw(d[[index]], d$Site)
      post <- exact_wilcox_pairs(d[[index]], d$Site, kw$p_exact)
      label <- data.frame(Matrix = matrix_name, Cohort = cohort, Estimate = estimation,
                          Date = date, Hill_order = index)
      KW_rows[[length(KW_rows) + 1L]] <- cbind(label, kw)
      pair_rows[[length(pair_rows) + 1L]] <- cbind(label[rep(1L,nrow(post)), ], post)
    }
  }
}
KW <- bind_rows(KW_rows)
pairs <- bind_rows(pair_rows)
readr::write_tsv(KW, "results/tables/alpha_global.tsv")
readr::write_tsv(pairs, "results/tables/alpha_pairs.tsv")
# March q = 1 is a useful check: SG vs BQ passes Holm, but the primary global test does not.
print(subset(pairs, Matrix == "Primary_bacteria" & Cohort == "With_BB05" &
             Estimate == "Common_coverage" & Date == "March" & Hill_order == "D1"))

# 5. Hellinger transformation and explicit permutation matrices ----
# Use Euclidean distances between Hellinger-transformed sample profiles.
# Permutation generation:
otu_beta <- t(main_counts)
otu_beta_Ngt1 <- t(filtered_counts)
meta_beta <- meta[rownames(otu_beta), , drop = FALSE]
otu_hell <- decostand(otu_beta, method = "hellinger")
otu_hell_Ngt1 <- decostand(otu_beta_Ngt1, method = "hellinger")
dist_beta <- dist(otu_hell, method = "euclidean")
hellinger <- list(Primary_bacteria = otu_hell, Occurrence_filtered_bacteria = otu_hell_Ngt1)
P_beta <- list()
for (n in c(25L, 24L, 12L, 11L, 13L, 8L, 7L, 10L, 6L, 9L)) {
  set.seed(seed)
  P_beta[[as.character(n)]] <- shuffleSet(n, nset = nperm, control = how(nperm = nperm))
}
# 6. Test site, sampling period and their interaction; check dispersion ----
# No pairing or blocks here. The restricted permutations used later belong to the PARTIAL RDA only.
beta_models <- dispersion_models <- beta_designs <- list()
for (matrix_name in names(matrices)) for (cohort in cohorts) {
  ids <- sample_sets[[cohort]]
  m <- droplevels(meta[ids, , drop = FALSE])
  Y <- hellinger[[matrix_name]][ids, , drop = FALSE]
  dis <- dist(Y)
  P <- P_beta[[as.character(length(ids))]]
  key <- paste(matrix_name, cohort, "Global_Site_Date", sep = "|")
  beta_models[[key]] <- adonis2(dis ~ Site * Date, data = m, permutations = P)
  beta_designs[[key]] <- list(metadata = m, group = m$Group, family = NA_character_, permutations = P)
  bd <- betadisper(dis, m$Group, type = "median", bias.adjust = TRUE)
  dispersion_models[[key]] <- list(model = bd, test = permutest(bd, permutations = P))
  key_int <- paste(matrix_name, cohort, "Site_Date_interaction", sep = "|")
  beta_models[[key_int]] <- adonis2(dis ~ Site * Date, data = m, permutations = P, by = "margin")
  beta_designs[[key_int]] <- beta_designs[[key]]

  # Construct each follow-up from its actual samples. Never reuse a 25-row design for 24 samples.
  comparisons <- list()
  for (date in dates) comparisons[[paste0("Sites_within_",date)]] <-
    list(ids = ids[m$Date == date], term = "Site", family = "Sites_within_two_dates")
  for (site in sites) comparisons[[paste0("Dates_within_",site)]] <-
    list(ids = ids[m$Site == site], term = "Date", family = "Dates_within_three_sites")
  for (date in dates) for (pair in combn(sites, 2, simplify = FALSE)) {
    comparisons[[paste("Pair",date,pair[1],pair[2],sep="_")]] <-
      list(ids = ids[m$Date == date & m$Site %in% pair], term = "Site", family = paste0("Site_pairs_",date))
  }
  for (contrast in names(comparisons)) {
    plan <- comparisons[[contrast]]
    submeta <- droplevels(m[plan$ids, , drop = FALSE])
    dis_sub <- dist(Y[plan$ids, , drop = FALSE])
    P <- P_beta[[as.character(nrow(submeta))]]
    key <- paste(matrix_name, cohort, contrast, sep = "|")
    if (plan$term == "Site") {
      beta_models[[key]] <- adonis2(dis_sub ~ Site, data = submeta, permutations = P)
    } else {
      beta_models[[key]] <- adonis2(dis_sub ~ Date, data = submeta, permutations = P)
    }
    group <- submeta[[plan$term]]
    beta_designs[[key]] <- list(metadata = submeta, group = group, family = plan$family, permutations = P)
    bd <- betadisper(dis_sub, group, type = "median", bias.adjust = TRUE)
    dispersion_models[[key]] <- list(model = bd, test = permutest(bd, permutations = P))
  }
}


# Collect the fitted models into compact reporting tables.  This loop extracts
# statistics; it does not choose or refit a model.
beta_rows <- dispersion_rows <- permutation_rows <- list()
for (model_key in names(beta_models)) {
  labels <- strsplit(model_key, "|", fixed = TRUE)[[1]]
  matrix_name <- labels[1]
  cohort <- labels[2]
  comparison <- labels[3]
  model <- beta_models[[model_key]]
  design <- beta_designs[[model_key]]
  model_data <- design$metadata
  group <- design$group
  family <- design$family
  P <- design$permutations
  is_interaction <- comparison == "Site_Date_interaction"
  term <- if (is_interaction)
    "Site:Date" else "Model"
  beta_rows[[length(beta_rows) + 1L]] <- data.frame(Matrix = matrix_name, Cohort = cohort,
    Comparison = comparison, n = nrow(model_data), df = model[term, "Df"], df_residual = model["Residual",
      "Df"], F = model[term, "F"], R2 = model[term, "R2"], p = model[term, "Pr(>F)"],
    p_Holm = NA_real_, Holm_family = family)
  allocation_possible <- allocation_used <- NA_real_
  if (!comparison %in% c("Global_Site_Date", "Site_Date_interaction")) {
    allocation_possible <- round(exp(lfactorial(length(group)) - sum(lfactorial(table(group)))))
    labels <- as.integer(group)
    keys <- apply(P, 1, function(p) paste(labels[order(p)], collapse = ","))
    allocation_used <- length(unique(c(paste(labels, collapse = ","), keys)))
  }
  unique_permutations <- nrow(unique(as.matrix(P)))
  permutation_rows[[length(permutation_rows) + 1L]] <- data.frame(Matrix = matrix_name,
    Cohort = cohort, Comparison = comparison, n = nrow(model_data), Permutations_requested = nperm,
    Permutations_generated = nrow(P), Unique_index_permutations = unique_permutations, Exact_index_enumeration = abs(lfactorial(nrow(model_data)) -
      log(unique_permutations + 1)) < 1e-08, Possible_label_allocations = allocation_possible,
    Label_allocations_seen_including_observed = allocation_used)

  if (!is_interaction) {
    dt <- dispersion_models[[model_key]]$test$tab
    dispersion_rows[[length(dispersion_rows) + 1L]] <- data.frame(Matrix = matrix_name,
      Cohort = cohort, Comparison = comparison, n = nrow(model_data), df = dt[1,
        "Df"], df_residual = dt[2, "Df"], F = dt[1, "F"], p = dt[1, "Pr(>F)"],
      p_Holm = NA_real_, Holm_family = if (startsWith(comparison, "Pair_"))
        family else NA_character_)
  }
}
beta <- bind_rows(beta_rows)
dispersion <- bind_rows(dispersion_rows)
permutation_audit <- bind_rows(permutation_rows)
permutation_audit$Seed <- seed
permutation_audit$Restriction <- "Unrestricted within each fitted data subset; samples are unpaired"
# Indices permute sample rows; several row permutations can represent the same labeling.
design_keys <- paste(permutation_audit$Matrix,permutation_audit$Cohort,
                     permutation_audit$Comparison,sep="|")
permutation_audit$Group_sizes <- vapply(design_keys,function(k) {
  nn <- table(droplevels(factor(beta_designs[[k]]$group)))
  paste(paste(names(nn),as.integer(nn),sep=":"),collapse="; ")
},character(1))
permutation_audit$Min_index_p_resolution <- 1/(1+permutation_audit$Permutations_generated)
permutation_audit$PERMANOVA_label_grid_if_exhaustive <- with(permutation_audit,
  ifelse(Exact_index_enumeration & !is.na(Possible_label_allocations),
         1/Possible_label_allocations, NA_real_))
# The PERMANOVA label grid is a resolution, not a guaranteed attainable P: ties or symmetries may coarsen it.
# PERMDISP permutes model residuals; do not transfer the PERMANOVA label grid to that test.

for (matrix_name in names(matrices)) for (cohort in cohorts) {
  for (family in c("Dates_within_three_sites", "Sites_within_two_dates", "Site_pairs_August", "Site_pairs_March")) {
    idx <- which(beta$Matrix == matrix_name & beta$Cohort == cohort & beta$Holm_family ==
      family)
    beta$p_Holm[idx] <- p.adjust(beta$p[idx], "holm")
    idx <- which(dispersion$Matrix == matrix_name & dispersion$Cohort == cohort &
      dispersion$Holm_family == family)
    dispersion$p_Holm[idx] <- p.adjust(dispersion$p[idx], "holm")
  }
}
dispersion$Interpretation <- ifelse(ifelse(is.na(dispersion$p_Holm), dispersion$p, dispersion$p_Holm) <
  0.05, "Dispersion heterogeneity detected", "No heterogeneity detected")
readr::write_tsv(beta, "results/tables/PERMANOVA.tsv")
readr::write_tsv(dispersion, "results/tables/PERMDISP.tsv")
readr::write_tsv(permutation_audit, "results/tables/permutation_audit.tsv")

