# 8. Complete-case RDA: pooled and conditional associations ----
# Pooled RDA combines sites and dates. Partial RDA conditions on Site-Date and
# restricts permutations to those groups. Interpret both as associations.
# Forward tests of constrained axes: split the existing 9,999 permutation rows into blocks
# to avoid allocating the full ASV-by-permutation workspace. Recombine F statistics, not P values.
# Global and marginal tests below use vegan::anova.cca directly.
test_rda_axes <- function(fit, permutations) {
  blocks <- split(seq_len(nrow(permutations)), ceiling(seq_len(nrow(permutations)) / 100))
  distributions <- vector("list", length(blocks))
  for (b in seq_along(blocks)) {
    P <- permutations[blocks[[b]], , drop = FALSE]
    attr(P, "control") <- attr(permutations, "control")
    attr(P, "seed") <- attr(permutations, "seed")
    z <- vegan::anova.cca(fit, permutations = P, by = "axis", model = "reduced", parallel = 1, cutoff = Inf)
    if (b == 1L) result <- z
    distributions[[b]] <- attr(z, "F.perm")
  }
  perm_F <- do.call(rbind, distributions)
  a <- seq_len(ncol(perm_F))
  p <- (1 + colSums(sweep(perm_F, 2, result$F[a] - sqrt(.Machine$double.eps), ">="))) / (1 + nrow(perm_F))
  p <- cummax(p)
  first_stop <- match(TRUE, p >= 1)
  if (!is.na(first_stop) && first_stop < length(a)) {
    later <- seq.int(first_stop + 1L, length(a))
    p[later] <- NA_real_
    perm_F[, later] <- NA_real_
    df <- stats::nobs(fit) - length(fit$CCA$eig) - max(c(0L, fit$pCCA$QR$rank)) - 1L
    result$F[later] <- (fit$CCA$eig / fit$CA$tot.chi * df)[later]
  }
  result[["Pr(>F)"]][a] <- p
  attr(result, "F.perm") <- perm_F
  attr(result, "Random.seed") <- attr(permutations, "seed")
  attr(result, "control") <- attr(permutations, "control")
  result
}

