environment_CC[, predictors] <- scale(environment[CC_ids$With_BB05, environment_names])
environment_CC$Group <- interaction(factor(environment_CC$Site, levels = sites), factor(environment_CC$Date,
  levels = dates), sep = "__", drop = TRUE)
# Each cohort gets its own valid permutation matrix. A 16-column matrix is never
# truncated to 15 columns. The 16-case standardization is retained without BB_05.
P_RDA <- P_partial <- list()
for (cohort in cohorts) {
  ids <- CC_ids[[cohort]]
  set.seed(seed)
  P_RDA[[cohort]] <- shuffleSet(length(ids), nset = nperm, control = how(nperm = nperm))
  set.seed(seed)
  P_partial[[cohort]] <- shuffleSet(length(ids), nset = nperm, control = how(nperm = nperm,
    blocks = droplevels(environment_CC[ids, "Group"]), within = Within(type = "free")))
  colnames(P_RDA[[cohort]]) <- colnames(P_partial[[cohort]]) <- ids
}
