# Extract global, marginal, axis and diagnostic results without refitting.
RDA_global_rows <- RDA_variables_rows <- RDA_axes_rows <- RDA_reduced_rows <- list()
RDA_vif_rows <- RDA_correlation_rows <- RDA_permutation_rows <- list()
for (key in names(RDA_tests)) {
  labels <- strsplit(key, "|", fixed = TRUE)[[1]]
  matrix_name <- labels[1]
  cohort <- labels[2]
  model_name <- labels[3]
  ids <- CC_ids[[cohort]]
  D <- environment_CC[ids, , drop = FALSE]
  D$Group <- droplevels(D$Group)
  fit <- RDA_models[[key]]
  ag <- RDA_tests[[key]]$global
  P <- if (model_name == "Pooled")
    P_RDA[[cohort]] else P_partial[[cohort]]
  R2 <- RsquareAdj(fit)
  RDA_global_rows[[length(RDA_global_rows) + 1L]] <- data.frame(Matrix = matrix_name,
    Cohort = cohort, Model = model_name, n = length(ids), df_conditioning = if (model_name ==
      "Pooled")
      0L else fit$pCCA$rank, df_model = ag["Model", "Df"], df_residual = ag["Residual",
      "Df"], F = ag["Model", "F"], R2 = R2$r.squared, R2_adjusted = R2$adj.r.squared,
    p = ag["Model", "Pr(>F)"], p_adjusted = NA_real_, Permutations_generated = nrow(P), Adjustment_family = "No adjustment across sensitivity scenarios",
    Scheme = if (model_name == "Pooled")
      "Unrestricted; reduced model" else "Within Site-Date; reduced model")
  # Duplicate index rows in Monte Carlo draws are recorded and retained.
  permutation_keys <- apply(P, 1, paste, collapse = ",")
  identity_key <- paste(seq_along(ids), collapse = ",")
  possible <- if (model_name == "Pooled")
    factorial(length(ids)) else prod(factorial(table(D$Group)))
  RDA_permutation_rows[[length(RDA_permutation_rows) + 1L]] <- data.frame(Matrix = matrix_name,
    Cohort = cohort, Model = model_name, n = length(ids), Permutations_generated = nrow(P),
    Unique_index_permutations = length(unique(permutation_keys)), Identity_rows = sum(permutation_keys ==
      identity_key), Possible_index_arrangements = possible, Seed = seed)
  if (matrix_name != "Primary_bacteria" || model_name != "Pooled")
    next
  # Marginal effects test one predictor conditional on the other two.
  am <- RDA_tests[[key]]$marginal
  ae <- RDA_tests[[key]]$axes
  RDA_tests[[key]]$marginal <- am
  RDA_tests[[key]]$axes <- ae
  RDA_variables_rows[[cohort]] <- data.frame(Cohort = cohort, Variable = predictors,
    n = length(ids), df = am[predictors, "Df"], df_residual = am["Residual", "Df"],
    F = am[predictors, "F"], R2_marginal = am[predictors, "Variance"]/fit$tot.chi,
    p = am[predictors, "Pr(>F)"], p_Holm = p.adjust(am[predictors, "Pr(>F)"], "holm"),
    Holm_family = "Three marginal environmental predictors within cohort", Permutations_generated = nrow(P))
  eigenvalues <- eigenvals(fit, model = "constrained")
  axes <- names(eigenvalues)
  RDA_axes_rows[[cohort]] <- data.frame(Cohort = cohort, Axis = axes, n = length(ids),
    df_axis = ae[axes, "Df"], df_residual = ae["Residual", "Df"], Percent_total = 100 *
      as.numeric(eigenvalues)/fit$tot.chi, Percent_constrained = 100 * as.numeric(eigenvalues)/sum(eigenvalues),
    F = ae[axes, "F"], p = ae[axes, "Pr(>F)"], Permutations_generated = nrow(P), Procedure = "Forward by-axis tests; no additional Holm adjustment")
  vv <- vif.cca(fit)
  RDA_vif_rows[[cohort]] <- data.frame(Cohort = cohort, Variable = names(vv), VIF = unname(vv))
  for (pair in combn(predictors, 2, simplify = FALSE)) {
    RDA_correlation_rows[[length(RDA_correlation_rows) + 1L]] <- data.frame(Cohort = cohort,
      Variable1 = pair[1], Variable2 = pair[2], n = length(ids), Spearman = cor(D[[pair[1]]],
        D[[pair[2]]], method = "spearman"))
  }
}
for (key in names(RDA_reduced_tests)) {
  labels <- strsplit(key, "|", fixed = TRUE)[[1]]
  cohort <- labels[2]
  reduced_name <- labels[3]
  ids <- CC_ids[[cohort]]
  reduced <- RDA_models[[key]]
  ar <- RDA_reduced_tests[[key]]
  rr <- RsquareAdj(reduced)
  RDA_reduced_rows[[length(RDA_reduced_rows) + 1L]] <- data.frame(Cohort = cohort,
    Model = reduced_name, n = length(ids), df_model = ar["Model", "Df"], df_residual = ar["Residual",
      "Df"], F = ar["Model", "F"], R2 = rr$r.squared, R2_adjusted = rr$adj.r.squared,
    p = ar["Model", "Pr(>F)"], Permutations_generated = nrow(P_RDA[[cohort]]))
}
RDA_global <- bind_rows(RDA_global_rows)
