# 9. Secondary imputed RDA and algorithmic stability ----
# Use only OM, TN and Olsen P in missForest.
# The 100-seed check describes algorithmic variation; it does not propagate
# uncertainty in the missing measurements into RDA inference.
imputation_order <- environment$ID[rowSums(!is.na(environment[,environment_names])) >= 2]
eligible <- environment$ID[rowSums(!is.na(environment[, environment_names])) >= 2]
stopifnot(setequal(imputation_order, eligible), length(eligible) == 20L)
env_imp <- environment[imputation_order, , drop = FALSE]
env_imp_matrix <- env_imp[, environment_names, drop = FALSE]
set.seed(seed)
mf_env <- missForest(env_imp_matrix, ntree = 500, maxiter = 10, variablewise = TRUE, verbose = FALSE)
env_imp_values <- mf_env$ximp
missing_positions <- which(is.na(as.matrix(env_imp_matrix)), arr.ind = TRUE)
stopifnot(nrow(missing_positions) == 4L, all(rowSums(is.na(env_imp_matrix)) <= 1), all(as.matrix(env_imp_values)[!is.na(env_imp_matrix)] ==
  as.matrix(env_imp_matrix)[!is.na(env_imp_matrix)]))
imputed_values <- data.frame(ID = rownames(env_imp_matrix)[missing_positions[, 1]], Variable = environment_names[missing_positions[,
  2]], Imputed_value = as.matrix(env_imp_values)[missing_positions])
OOB <- data.frame(Variable = environment_names, n_observed = colSums(!is.na(env_imp_matrix)),
  n_imputed = colSums(is.na(env_imp_matrix)), Returned_OOB = as.numeric(mf_env$OOBerror))
OOB$MSE_OOB <- ifelse(OOB$n_imputed > 0, OOB$Returned_OOB, NA_real_)
OOB$RMSE_OOB <- sqrt(OOB$MSE_OOB)
OOB$RMSE_over_observed_SD <- OOB$RMSE_OOB/vapply(env_imp_matrix, sd, numeric(1), na.rm = TRUE)
for (i in seq_len(nrow(imputed_values))) {
  id <- imputed_values$ID[i]
  variable <- imputed_values$Variable[i]
  observed <- env_imp_matrix[[variable]]
  same_group <- env_imp$Site == env_imp[id, "Site"] & env_imp$Date == env_imp[id, "Date"]
  within_group <- observed[same_group & !is.na(observed)]
  imputed_values$Min_observed_overall[i] <- min(observed, na.rm = TRUE)
  imputed_values$Max_observed_overall[i] <- max(observed, na.rm = TRUE)
  imputed_values$n_observed_group[i] <- length(within_group)
  imputed_values$Min_observed_group[i] <- min(within_group)
  imputed_values$Max_observed_group[i] <- max(within_group)
}
imp_check <- data.frame()
for (imputation_seed in 1:100) {
  set.seed(imputation_seed)
  tmp <- missForest(env_imp_matrix, ntree = 500, maxiter = 10, variablewise = TRUE, verbose = FALSE)$ximp
  imp_check <- rbind(imp_check, data.frame(seed = imputation_seed, BQ01_N = tmp["BQ_01",
    "Total N (%)"], BQ02M_N = tmp["BQ_02_M", "Total N (%)"], BQ03M_P = tmp["BQ_03_M",
    "Olsen P (mg/kg)"], SG02M_N = tmp["SG_02_M", "Total N (%)"]))
  if (imputation_seed%%20 == 0)
    message("Imputation stability: ", imputation_seed, "/100 seeds")
}
stability <- data.frame(Value = names(imp_check)[-1], t(vapply(imp_check[-1], function(x) c(Median = median(x),
  IQR = IQR(x), Min = min(x), Max = max(x)), numeric(4))))
Y_imp <- hellinger$Primary_bacteria[imputation_order, , drop = FALSE]
D_imp <- as.data.frame(scale(env_imp_values))
names(D_imp) <- predictors
set.seed(seed)
P_imp <- shuffleSet(length(imputation_order), nset = nperm, control = how(nperm = nperm))
RDA_imputed <- rda(Y_imp ~ Organic_Matter + Total_N + Olsen_P, data = D_imp, scale = FALSE)
ag_imp <- vegan::anova.cca(RDA_imputed, permutations = P_imp, model = "reduced")
am_imp <- vegan::anova.cca(RDA_imputed, permutations = P_imp, model = "reduced", by = "margin")
message("Testing RDA axes: secondary imputed analysis")
ae_imp <- test_rda_axes(RDA_imputed, P_imp)
rr <- RsquareAdj(RDA_imputed)
RDA_imputed_global <- data.frame(Analysis = "Secondary_imputation", n = length(imputation_order),
  df_model = ag_imp["Model", "Df"], df_residual = ag_imp["Residual", "Df"], F = ag_imp["Model",
    "F"], R2 = rr$r.squared, R2_adjusted = rr$adj.r.squared, p = ag_imp["Model", "Pr(>F)"],
  Permutations_generated = nrow(P_imp))
RDA_imputed_variables <- data.frame(Variable = predictors, n = length(imputation_order),
  df = am_imp[predictors, "Df"], df_residual = am_imp["Residual", "Df"], F = am_imp[predictors,
    "F"], R2_marginal = am_imp[predictors, "Variance"]/RDA_imputed$tot.chi, p = am_imp[predictors,
    "Pr(>F)"], p_Holm = p.adjust(am_imp[predictors, "Pr(>F)"], "holm"), Holm_family = "Three marginal predictors in secondary imputed RDA",
  Permutations_generated = nrow(P_imp))
ei <- eigenvals(RDA_imputed, model = "constrained")
axes <- names(ei)
RDA_imputed_axes <- data.frame(Axis = axes, n = length(imputation_order), df_axis = ae_imp[axes,
  "Df"], df_residual = ae_imp["Residual", "Df"], Percent_total = 100 * as.numeric(ei)/RDA_imputed$tot.chi,
  Percent_constrained = 100 * as.numeric(ei)/sum(ei), F = ae_imp[axes, "F"], p = ae_imp[axes,
    "Pr(>F)"], Permutations_generated = nrow(P_imp))
