# 10. Operational core: recurrence in the observed sample sets ----
# Define detection as >=0.1% and prevalence as >=80%, >=90% or 100%.
# Summarize recurrence within the observed sample sets. Unequal group sizes and
# sampling-period proportions remain limitations of these comparisons.
core_rows <- core_member_rows <- list()

for (matrix_name in names(matrices)) for (cohort in cohorts) {
  ids <- sample_sets[[cohort]]
  counts <- matrices[[matrix_name]][, ids, drop = FALSE]
  relative <- sweep(counts, 2, colSums(counts), "/")
  groups <- list(Regional = ids)
  for (site in sites) groups[[paste0("Site_", site)]] <- ids[meta[ids, "Site"] == site]
  for (date in dates) groups[[paste0("Date_", date)]] <- ids[meta[ids, "Date"] == date]
  for (group in names(groups)) for (prevalence in c(0.8, 0.9, 1)) {
    selected_ids <- groups[[group]]
    detected <- rowSums(relative[, selected_ids, drop = FALSE] >= 0.001)
    members <- names(detected)[detected/length(selected_ids) >= prevalence]
    core_rows[[length(core_rows) + 1L]] <- data.frame(Matrix = matrix_name, Cohort = cohort,
      Group = group, Prevalence = prevalence, Detection = 0.001, n = length(selected_ids),
      Minimum_detections = ceiling(prevalence * length(selected_ids)), n_core = length(members))
    if (length(members))
      core_member_rows[[length(core_member_rows) + 1L]] <- data.frame(Matrix = matrix_name,
        Cohort = cohort, Group = group, Prevalence = prevalence, ASV = members,
        n_detected = unname(detected[members]), n = length(selected_ids), taxonomy[members,
          c("Phylum", "Class", "Order", "Family", "Genus"), drop = FALSE], row.names = NULL)
  }
}
core_summary <- bind_rows(core_rows)
core_members <- bind_rows(core_member_rows)
readr::write_tsv(core_summary, "results/tables/core_summary.tsv")
readr::write_tsv(core_members, "results/tables/core_members.tsv")

