# 11. Descriptive taxonomic profiles: retain the complete denominator ----
# Calculate proportions within each library, then unweighted means across samples.
# Select displayed taxa using the 25-sediment cohort and retain that selection
# when excluding BB_05. Keep unassigned taxonomy in the library denominator.
taxon_counts <- taxon_percent <- taxon_profiles <- taxon_group_tables <- list()
missing_labels <- c(Family = "Unassigned_family", Genus = "Unresolved", Phylum = "Unassigned phylum")
for (rank_name in c("Family", "Genus", "Phylum")) {
  counts <- if (rank_name == "Phylum")
    bacterial_31 else main_counts
  labels <- trimws(as.character(taxonomy[rownames(counts), rank_name]))
  absent <- is.na(labels) | toupper(labels) %in% c("", "NA", "N/A", "NAN") | tolower(labels) %in%
    tolower(c(paste("Unknown", rank_name), missing_labels[[rank_name]]))
  labels[absent] <- missing_labels[[rank_name]]
  aggregated <- rowsum(counts, labels, reorder = FALSE)
  if (!missing_labels[[rank_name]] %in% rownames(aggregated)) {
    aggregated <- rbind(aggregated, matrix(0, nrow = 1, ncol = ncol(aggregated), dimnames = list(missing_labels[[rank_name]],
      colnames(aggregated))))
  }
  pct <- 100 * sweep(aggregated, 2, colSums(counts), "/")
  stopifnot(all(colSums(aggregated) == colSums(counts)), max(abs(colSums(pct) - 100)) <
    1e-10)
  taxon_counts[[rank_name]] <- aggregated
  taxon_percent[[rank_name]] <- pct
  profile <- data.frame(Taxon = rep(rownames(pct), times = ncol(pct)), ID = rep(colnames(pct),
    each = nrow(pct)), Reads = as.vector(aggregated), Percent = as.vector(pct))
  profile <- cbind(profile, metadata[profile$ID, c("Type", "Site", "Date"), drop = FALSE])
  rownames(profile) <- NULL
  taxon_profiles[[rank_name]] <- profile
  group_rows <- list()
  for (cohort in cohorts) for (type in if (rank_name == "Phylum")
    c("Sediment", "Sea_Water") else "Sediment") {
    for (site in c("All_sites", sites)) for (date in dates) {
      ids <- metadata$ID[metadata$Type == type & metadata$Date == date & (site ==
        "All_sites" | metadata$Site == site)]
      if (cohort == "Without_BB05")
        ids <- setdiff(ids, "BB_05")
      if (!length(ids))
        next
      z <- pct[, ids, drop = FALSE]
      group_rows[[length(group_rows) + 1L]] <- data.frame(Cohort = cohort, Type = type,
        Scope = if (site == "All_sites")
          "All_sites_pooled" else "Site_Date", Site = site, Date = date, Taxon = rownames(z), n = length(ids),
        Mean_pct = rowMeans(z), Median_pct = apply(z, 1, median), Min_pct = apply(z,
          1, min), Max_pct = apply(z, 1, max))
    }
  }
  taxon_group_tables[[rank_name]] <- bind_rows(group_rows)
  readr::write_tsv(profile, file.path(output, "tables", paste0(rank_name, "_sample_profiles.tsv")))
  readr::write_tsv(taxon_group_tables[[rank_name]], file.path(output, "tables", paste0(rank_name,
    "_group_profiles.tsv")))
}
