# 12. RDA plotting scores, descriptive ASV selection and core overlap ----
# Apply a common axis-sign choice to samples, ASVs and environmental arrows.
# Axis signs are arbitrary. Use an explicit graphical convention from the manuscript:
# the TN arrow points right (RDA1) and the OM arrow downward (RDA2).
# Apply the same flips to arrows, ASVs AND sample scores. Display only; no refitting.
RDA_sample_rows <- RDA_arrow_rows <- RDA_ASV_rows <- RDA_alignment_rows <- list()
for (cohort in cohorts) {
  fit <- RDA_models[[paste("Primary_bacteria",cohort,"Pooled",sep="|")]]
  bp_raw <- scores(fit,display="bp",choices=1:2,scaling=2)
  axis_sign <- sign(c(bp_raw["Total_N",1], -bp_raw["Organic_Matter",2]))
  stopifnot(all(is.finite(axis_sign)), all(axis_sign!=0))
  RDA_alignment_rows[[cohort]] <- data.frame(Cohort=cohort,Axis=c("RDA1","RDA2"),Sign=axis_sign)
  sp <- sweep(scores(fit, display = "species", choices = 1:2, scaling = 2), 2, axis_sign,
    "*")
  wa <- sweep(scores(fit, display = "sites", choices = 1:2, scaling = 2), 2, axis_sign, "*")
  bp <- sweep(scores(fit, display = "bp", choices = 1:2, scaling = 2), 2, axis_sign, "*")
  ids <- CC_ids[[cohort]]
  RDA_sample_rows[[cohort]] <- data.frame(Cohort = cohort, ID = rownames(wa), Site = meta[rownames(wa),
    "Site"], Date = meta[rownames(wa), "Date"], wa, row.names = NULL)
  RDA_arrow_rows[[cohort]] <- data.frame(Cohort = cohort, Variable = rownames(bp), bp,
    row.names = NULL)
  z <- data.frame(Cohort = cohort, taxonomy[rownames(sp), , drop = FALSE], sp, n_present_CC = rowSums(main_counts[rownames(sp),
    ids, drop = FALSE] > 0), Prevalence_CC = rowMeans(main_counts[rownames(sp), ids, drop = FALSE] >
    0), row.names = NULL)
  z$Taxon <- ifelse(!is.na(z$Genus) & nzchar(z$Genus), z$Genus, ifelse(!is.na(z$Family) &
    nzchar(z$Family), z$Family, NA_character_))
  z$Eligible <- z$Prevalence_CC >= 0.5 & abs(z$RDA1) >= 0.05
  pos <- which(z$Eligible & z$RDA1 > 0)
  neg <- which(z$Eligible & z$RDA1 < 0)
  pos <- pos[order(-z$RDA1[pos], z$ASV[pos])]
  neg <- neg[order(z$RDA1[neg], z$ASV[neg])]
  z$In_figure <- seq_len(nrow(z)) %in% c(head(pos,10), head(neg,10))
  z$Direction <- ifelse(z$RDA1 > 0, "Positive", "Negative")
  RDA_ASV_rows[[cohort]] <- z
}

