    height = 0, seed = seed), shape = 21, size = 2.8) + geom_text_repel(data = subset(alpha_plot,
    ID == "BB_05"), aes(label = ID), seed = seed, size = 3.3, min.segment.length = 0, nudge_x = 0.25) +
    geom_text(data = annotations, aes(x = 2, y = y, label = label), inherit.aes = FALSE,
      size = 3.6) + facet_grid(Hill_order ~ Date, scales = "free_y", labeller = labeller(Hill_order = c(D0 = "q = 0",
    D1 = "q = 1", D2 = "q = 2"))) + scale_fill_manual(values = site_colors, labels = site_labels,
    guide = "none") + scale_x_discrete(labels = site_labels) + scale_y_continuous(expand = expansion(mult = c(0.04,
    0.08))) + labs(x = NULL, y = "Effective number of ASVs", subtitle = paste(cohort_label,
