sensitivity_rows <- list()
comparisons <- data.frame(
  Type = c("Occurrence filter", "Occurrence filter", "BB_05"),
  Matrix_A = "Primary_bacteria",
  Cohort_A = c("With_BB05", "Without_BB05", "With_BB05"),
  Matrix_B = c(
    "Occurrence_filtered_bacteria",
    "Occurrence_filtered_bacteria",
    "Primary_bacteria"),
  Cohort_B = c("With_BB05", "Without_BB05", "Without_BB05"))

for (i in seq_len(nrow(comparisons))) {
  comparison_row <- comparisons[i, ]
  # Select the same samples in the same order for both scenarios.
  ids <- intersect(
    sample_sets[[comparison_row$Cohort_A]],
    sample_sets[[comparison_row$Cohort_B]])
  da <- dist(
    hellinger[[comparison_row$Matrix_A]][ids, , drop = FALSE])
  db <- dist(
    hellinger[[comparison_row$Matrix_B]][ids, , drop = FALSE])
  # Extract coordinates from the previously fitted NMDS models.
  key_a <- paste(
    comparison_row$Matrix_A, comparison_row$Cohort_A, sep = "|")
  key_b <- paste(
    comparison_row$Matrix_B, comparison_row$Cohort_B, sep = "|")
  a <- vegan::scores(
    NMDS_models[[key_a]], display = "sites")[ids, , drop = FALSE]
  b <- vegan::scores(
    NMDS_models[[key_b]], display = "sites")[ids, , drop = FALSE]
  proc <- vegan::procrustes(a, b, symmetric = TRUE)
  # Summarize distance agreement and Procrustes similarity.
  sensitivity_rows[[i]] <- data.frame(
    comparison_row,
    n_common = length(ids),
    Distance_Spearman = cor(as.vector(da), as.vector(db),
      method = "spearman"),
    Distance_Pearson = cor(as.vector(da), as.vector(db)),
    Max_distance_change = max(abs(da - db)),
    Procrustes_m2 = proc$ss,
    Procrustes_r = sqrt(max(0, 1 - proc$ss)))
}

