for (mname in names(matrices)) for (cohort in cohorts) {
  X <- matrices[[mname]][,sample_sets[[cohort]],drop=FALSE]
  composition[[length(composition)+1L]] <- data.frame(Matrix=mname, Cohort=cohort, Samples=ncol(X),
      ASVs=sum(rowSums(X)>0), Reads=sum(X))
}
readr::write_tsv(bind_rows(composition), file.path(sup, "S2E_sediment_matrices.tsv"))

# S3: sample read depths, both Hill estimates, then global and pairwise results with the global gate.
