readr::write_tsv(subset(pairs, Matrix==primary & Estimate=="Common_coverage"), file.path(sup,"S3C_exact_pairs_global_gate.tsv"))

# S4: raw and adjusted tests, families, and actual permutation spaces for small groups.
bn <- subset(beta, Matrix==primary); bd_tab <- subset(dispersion, Matrix==primary)
readr::write_tsv(bn[!startsWith(bn$Comparison,"Pair_"),], file.path(sup,"S4A_PERMANOVA.tsv"))
readr::write_tsv(bd_tab[!startsWith(bd_tab$Comparison,"Pair_"),], file.path(sup,"S4B_PERMDISP.tsv"))
