# S5: complete-case, reduced, conditional and imputed models remain distinct.
model_report <- bind_rows(subset(RDA_global,Matrix==primary),
                 mutate(RDA_reduced, Matrix=primary, df_conditioning=0L),
                 mutate(RDA_imputed_global, Matrix=primary, Cohort="With_BB05", Model="Pooled_imputed",df_conditioning=0L))
readr::write_tsv(model_report,file.path(sup,"S5A_RDA_models.tsv"))
design <- expand.grid(Site=sites,Date=dates,stringsAsFactors=FALSE)
for (i in seq_len(nrow(design))) {
  ids <- environment$ID[environment$Site == design$Site[i] & environment$Date == design$Date[i]]
  design$All_sediments[i] <- length(ids)
  design$Complete_cases[i] <- sum(ids %in% CC_ids$With_BB05)
