print(control_profile)  # Report actual control counts, including a nonzero result if present.
# Local versus regional recurrence: see the supporting sample-level detections for each ASV.
rel_sed <- sweep(main_counts,2,colSums(main_counts),"/")
focal_ids <- c("ASV_5","ASV_9","ASV_13")
by_sample <- as.data.frame(as.table(rel_sed[focal_ids, , drop=FALSE]))
names(by_sample) <- c("ASV","ID","Proportion")
by_sample$Detected <- by_sample$Proportion >= .001
readr::write_tsv(by_sample, "results/tables/focal_core_ASVs_by_sample.tsv")

# Descriptive axis agreement, including ASVs shown in Fig. 4; compare fitted vectors after sign alignment.
axis_check <- axis_asvs <- list()
display_ids <- subset(RDA_ASVs_figure,Cohort=="With_BB05")$ASV
for (i in seq_along(sensitivity_rows)) {
  comp <- sensitivity_rows[[i]][,c("Matrix_A","Cohort_A","Matrix_B","Cohort_B")]
  a <- RDA_models[[paste(comp$Matrix_A,comp$Cohort_A,"Pooled",sep="|")]]
  b <- RDA_models[[paste(comp$Matrix_B,comp$Cohort_B,"Pooled",sep="|")]]
  va <- a$CCA$v[,1]; vb <- b$CCA$v[,1]
  both <- intersect(names(va),names(vb)); all_asvs <- union(names(va),names(vb))
  u <- v <- setNames(numeric(length(all_asvs)),all_asvs)
  u[names(va)] <- va; v[names(vb)] <- vb
  sgn <- if (sum(u*v)<0) -1 else 1
  v <- sgn*v; vb <- sgn*vb
  cosine <- sum(u*v)/sqrt(sum(u*u)*sum(v*v))
  ids <- intersect(rownames(a$CCA$u),rownames(b$CCA$u))
  YA <- hellinger[[comp$Matrix_A]][CC_ids[[comp$Cohort_A]],both,drop=FALSE]
  YB <- hellinger[[comp$Matrix_B]][CC_ids[[comp$Cohort_B]],both,drop=FALSE]
  informative <- both[colSums(sweep(YA,2,YA[1,], "!="))>0 | colSums(sweep(YB,2,YB[1,], "!="))>0]
  axis_check[[i]] <- cbind(comp, data.frame(ASVs_union=length(all_asvs), ASVs_variable_in_either=length(informative),
      Cosine=cosine, Angle_degrees=acos(pmax(-1,pmin(1,cosine)))*180/pi,
      Common_rank_Spearman=cor(va[informative],vb[informative],method="spearman"),
      LC_sample_Pearson=cor(a$CCA$u[ids,1],sgn*b$CCA$u[ids,1]), n_shared=length(ids)))
  axis_asvs[[i]] <- cbind(comp[rep(1,length(display_ids)),],data.frame(ASV=display_ids,
      Present_A=display_ids %in% names(va), Present_B=display_ids %in% names(vb),
      Direction_changed=unname(sign(va[display_ids])!=sign(vb[display_ids]))))
}
readr::write_tsv(bind_rows(axis_check),"results/tables/RDA1_matrix_and_sample_sensitivity.tsv")
readr::write_tsv(bind_rows(axis_asvs),"results/tables/RDA1_figure_ASVs_sensitivity.tsv")

# Optional descriptive influence check: delete each August BB complete case in turn.
# Compute effect sizes only; no new families of permutation P values are introduced.
influence <- list()
for (id in intersect(bb_august,cc)) {
  ids <- setdiff(cc,id)
  d <- droplevels(environment_CC[ids,,drop=FALSE]); y <- hellinger[[primary]][ids,,drop=FALSE]
  fit <- rda(y ~ Organic_Matter + Total_N + Olsen_P + Condition(Group),data=d)
  rr <- RsquareAdj(fit)
  influence[[id]] <- data.frame(Omitted=id,n=length(ids),R2=rr$r.squared,R2_adjusted=rr$adj.r.squared)
}
readr::write_tsv(bind_rows(influence),"results/tables/RDA_partial_leave_one_BB_August_out.tsv")

